from itertools import product
import copy
import sys
sys.setrecursionlimit(1 << 20)

N, H, W = map(int, input().split())
AB = list()

for _ in range(N):
    a, b = map(int, input().split())
    AB.append([a, b])

global ans
ans = False
C = [[True for _ in range(W)] for i in range(H)]

def dfs(x, y, rem, masu):
    global ans
    if all(all(row) for row in masu):
        ans = True
        return

    if y == W:
        x += 1
        y = 0

    if x == H:
        return

    if masu[x][y]:
        dfs(x, y + 1, rem, masu)
        return

    for i in range(len(rem)):
        for orientation in [(rem[i][0], rem[i][1]), (rem[i][1], rem[i][0])]:
            a, b = orientation
            if x + a <= H and y + b <= W:
                can_place = True
                for dx in range(a):
                    for dy in range(b):
                        if masu[x + dx][y + dy]:
                            can_place = False
                            break
                    if not can_place:
                        break

                if can_place:
                    for dx in range(a):
                        for dy in range(b):
                            masu[x + dx][y + dy] = True

                    dfs(x, y + b, rem[:i] + rem[i + 1:], masu)

                    for dx in range(a):
                        for dy in range(b):
                            masu[x + dx][y + dy] = False

for bits in product([0, 1], repeat=N):
    item = [AB[i] for i in range(N) if bits[i]]
    masu = [[False for _ in range(W)] for _ in range(H)]
    csum = sum(p[0] * p[1] for p in item)
    if csum == H * W:
        dfs(0, 0, item, masu)

if ans:
    print("Yes")
else:
    print("No")
